package api

// Admin user management (S11 S4): super_admin only (spec route table). A temporary password is
// generated by the server, returned once, and sets must_change_password (criterion 11); the last
// active super_admin cannot be demoted or disabled (criterion 10, locked in SQL).

import (
	"errors"
	"net/http"

	"github.com/google/uuid"

	"github.com/CrimsonCoder42/red_lite_cache/internal/adminauth"
	"github.com/CrimsonCoder42/red_lite_cache/protocol"
)

// listUsers answers GET /admin/users: one keyset page on (created_at, id), never a hash.
func (s *Server) listUsers(w http.ResponseWriter, r *http.Request) {
	limit, c, ok := s.pageParams(w, r)
	if !ok {
		return
	}
	var afterID uuid.UUID
	if c.id != "" {
		id, err := uuid.Parse(c.id)
		if err != nil {
			s.fail(w, r, http.StatusBadRequest, "invalid cursor")
			return
		}
		afterID = id
	}
	rows, err := s.admins.Users(r.Context(), c.at, afterID, limit+1)
	if err != nil {
		s.internalError(w, r, "list users", err)
		return
	}
	page := protocol.Page[UserInfo]{Items: make([]UserInfo, 0, min(len(rows), limit))}
	for i, u := range rows {
		if i == limit {
			last := rows[limit-1]
			page.NextCursor = cursor{at: last.CreatedAt, id: last.ID.String()}.encode()
			break
		}
		page.Items = append(page.Items, userInfo(u))
	}
	writeJSON(w, http.StatusOK, page)
}

// createUser answers POST /admin/users (201 with the temporary password, 409 email taken).
func (s *Server) createUser(w http.ResponseWriter, r *http.Request) {
	who, _ := s.authenticate(r, false)
	var req CreateUserRequest
	if !decode(w, r, &req) {
		return
	}
	role := adminauth.ParseRole(req.Role)
	if !validEmail(req.Email) || !validName(req.Name) || role == adminauth.RoleNone {
		s.fail(w, r, http.StatusBadRequest, "invalid email, name or role")
		return
	}
	pw, hash, ok := s.tempPassword(w, r)
	if !ok {
		return
	}
	u, err := s.admins.CreateUser(r.Context(), req.Email, req.Name, role, hash, who.user)
	switch {
	case errors.Is(err, ErrConflict):
		s.fail(w, r, http.StatusConflict, "email taken")
		return
	case err != nil:
		s.internalError(w, r, "create user", err)
		return
	}
	s.portalAudit(who.actor, "admin_user_created", u.ID.String(), map[string]string{"user_id": u.ID.String(), "role": role.String()})
	writeJSON(w, http.StatusCreated, CreateUserResponse{User: userInfo(u), TemporaryPassword: pw})
}

// patchUser answers PATCH /admin/users/{id}: role and/or disabled. Disabling ends every session.
func (s *Server) patchUser(w http.ResponseWriter, r *http.Request) {
	who, _ := s.authenticate(r, false)
	id, ok := s.pathID(w, r, "id", "user")
	if !ok {
		return
	}
	var req PatchUserRequest
	if !decode(w, r, &req) {
		return
	}
	if req.Role == nil && req.Disabled == nil {
		s.fail(w, r, http.StatusBadRequest, "role or disabled required")
		return
	}
	var role *adminauth.Role
	if req.Role != nil {
		ro := adminauth.ParseRole(*req.Role)
		if ro == adminauth.RoleNone {
			s.fail(w, r, http.StatusBadRequest, "invalid role")
			return
		}
		role = &ro
	}
	u, err := s.admins.UpdateUser(r.Context(), id, role, req.Disabled)
	switch {
	case errors.Is(err, ErrNotFound):
		s.fail(w, r, http.StatusNotFound, "user not found")
		return
	case errors.Is(err, ErrLastSuperAdmin):
		s.fail(w, r, http.StatusConflict, "last active super_admin")
		return
	case err != nil:
		s.internalError(w, r, "update user", err, "user", id.String())
		return
	}
	detail := map[string]string{"user_id": id.String()}
	if role != nil {
		detail["role"] = role.String()
	}
	if req.Disabled != nil {
		detail["disabled"] = boolString(*req.Disabled)
	}
	s.portalAudit(who.actor, "admin_user_updated", id.String(), detail)
	writeJSON(w, http.StatusOK, userInfo(u))
}

// resetPassword answers POST /admin/users/{id}/reset-password: a temporary password once, every
// session of the user ends, the lockout clears, must_change_password is set.
func (s *Server) resetPassword(w http.ResponseWriter, r *http.Request) {
	who, _ := s.authenticate(r, false)
	id, ok := s.pathID(w, r, "id", "user")
	if !ok {
		return
	}
	pw, hash, ok := s.tempPassword(w, r)
	if !ok {
		return
	}
	switch err := s.admins.SetPassword(r.Context(), id, hash, true, nil); {
	case errors.Is(err, ErrNotFound):
		s.fail(w, r, http.StatusNotFound, "user not found")
		return
	case err != nil:
		s.internalError(w, r, "reset password", err, "user", id.String())
		return
	}
	s.portalAudit(who.actor, "admin_password_reset", id.String(), map[string]string{"user_id": id.String()})
	writeJSON(w, http.StatusOK, ResetPasswordResponse{TemporaryPassword: pw})
}

func (s *Server) tempPassword(w http.ResponseWriter, r *http.Request) (pw, hash string, ok bool) {
	pw, err := adminauth.TempPassword()
	if err == nil {
		hash, err = adminauth.HashPassword(pw, s.bcryptCost)
	}
	if err != nil {
		s.internalError(w, r, "temporary password", err)
		return "", "", false
	}
	return pw, hash, true
}

func boolString(b bool) string {
	if b {
		return "true"
	}
	return "false"
}
